class Solution {
    public int strangePrinter(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                dp[i][j] = dp[i][j - 1] + 1;
                for (int k = i; k < j; k++) {
                    if (s.charAt(k) == s.charAt(j)) {
                        dp[i][j] = Math.min(dp[i][j], dp[i][k] + (k + 1 <= j - 1 ? dp[k + 1][j - 1] : 0));
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

class Solution {
    private int[][] memo;

    public int strangePrinter(String s) {
        int n = s.length();
        memo = new int[n][n];
        return solve(s, 0, n - 1);
    }

    private int solve(String s, int i, int j) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i][j] != 0) return memo[i][j];
        int result = solve(s, i, j - 1) + 1;
        for (int k = i; k < j; k++) {
            if (s.charAt(k) == s.charAt(j)) {
                result = Math.min(result, solve(s, i, k) + solve(s, k + 1, j - 1));
            }
        }
        memo[i][j] = result;
        return result;
    }
}

class Solution {
    public int strangePrinter(String s) {
        StringBuilder compact = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (compact.length() == 0 || compact.charAt(compact.length() - 1) != ch) {
                compact.append(ch);
            }
        }

        String t = compact.toString();
        int n = t.length();
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                dp[i][j] = dp[i + 1][j] + 1;
                for (int split = i + 1; split <= j; split++) {
                    if (t.charAt(split) == t.charAt(i)) {
                        int middle = split == i + 1 ? 0 : dp[i + 1][split - 1];
                        dp[i][j] = Math.min(dp[i][j], middle + dp[split][j]);
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

class Solution {
    private String text;
    private int[][] memo;

    public int strangePrinter(String s) {
        text = compress(s);
        int n = text.length();
        memo = new int[n][n];
        return dfs(0, n - 1);
    }

    private int dfs(int left, int right) {
        if (left > right) {
            return 0;
        }
        if (left == right) {
            return 1;
        }
        if (memo[left][right] != 0) {
            return memo[left][right];
        }

        int best = dfs(left + 1, right) + 1;
        for (int same = left + 1; same <= right; same++) {
            if (text.charAt(same) == text.charAt(left)) {
                int middle = dfs(left + 1, same - 1);
                int suffix = dfs(same, right);
                best = Math.min(best, middle + suffix);
            }
        }
        memo[left][right] = best;
        return best;
    }

    private String compress(String s) {
        StringBuilder compact = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (compact.length() == 0 || compact.charAt(compact.length() - 1) != ch) {
                compact.append(ch);
            }
        }
        return compact.toString();
    }
}
